mapper.select:
SELECT res.ID_ AS id, res.NAME_ AS name, def.NAME_ AS category, def.KEY_ AS processDefinitionKey, res.START_TIME_ AS createTime, res.END_TIME_ AS endTime, u.nickname AS startUserNickname,
/* 1. 来文单位、紧急程度、办结时限 */ (SELECT var.TEXT_ FROM ACT_HI_VARINST var WHERE var.PROC_INST_ID_ = res.ID_ AND var.NAME_ = #{VAR_SOURCE_UNIT} LIMIT 1) AS sourceUnit, (SELECT var.TEXT_ FROM ACT_HI_VARINST var WHERE var.PROC_INST_ID_ = res.ID_ AND var.NAME_ = #{VAR_URGENCY} LIMIT 1) AS urgencyDegree, (SELECT CASE WHEN var.LONG_ IS NOT NULL THEN to_char(to_timestamp(var.LONG_ / 1000), 'YYYY-MM-DD HH24:MI:SS') ELSE var.TEXT_ END FROM ACT_HI_VARINST var WHERE var.PROC_INST_ID_ = res.ID_ AND var.NAME_ = #{VAR_DEADLINE} LIMIT 1) AS deadlineDate,
/* 2. 引擎运行状态 (1:运行中, 2:正常完成, 3:异常结束/取消) */ (CASE WHEN res.END_TIME_ IS NULL THEN 1 WHEN res.END_TIME_ IS NOT NULL AND res.DELETE_REASON_ IS NULL THEN 2 WHEN res.END_TIME_ IS NOT NULL AND (res.DELETE_REASON_ = 'MI_END' OR LOWER(res.DELETE_REASON_) = 'completed') THEN 2 ELSE 3 END) AS status,
/* 3. 真实业务结果 (通过、驳回、撤回等) */ (SELECT COALESCE(CAST(var.LONG_ AS VARCHAR), var.TEXT_) FROM ACT_HI_VARINST var WHERE var.PROC_INST_ID_ = res.ID_ AND var.NAME_ = #{VAR_PROCESS_RESULT} LIMIT 1) AS processResult, (SELECT COALESCE(CAST(var.LONG_ AS VARCHAR), var.TEXT_) FROM ACT_HI_VARINST var WHERE var.PROC_INST_ID_ = res.ID_ AND var.NAME_ = #{VAR_PROCESS_STATUS} LIMIT 1) AS processStatus, (SELECT var.TEXT_ FROM ACT_HI_VARINST var WHERE var.PROC_INST_ID_ = res.ID_ AND var.NAME_ = #{VAR_PROCESS_REASON} LIMIT 1) AS processReason,
/* 4. 环节与办理人 */ (SELECT string_agg(t.NAME_, ', ') FROM ACT_RU_TASK t WHERE t.PROC_INST_ID_ = res.ID_) AS currTaskName, (SELECT string_agg(tu.nickname, ', ') FROM ACT_RU_TASK t LEFT JOIN system_users tu ON t.ASSIGNEE_ = CAST(tu.id AS VARCHAR) WHERE t.PROC_INST_ID_ = res.ID_) AS currTaskAssignee
FROM ACT_HI_PROCINST res LEFT JOIN ACT_RE_PROCDEF def ON res.PROC_DEF_ID_ = def.ID_ LEFT JOIN system_users u ON res.START_USER_ID_ = CAST(u.id AS VARCHAR)
(res.START_USER_ID_ = CAST(#{userId} AS VARCHAR) OR EXISTS (SELECT 1 FROM ACT_HI_TASKINST t WHERE t.PROC_INST_ID_ = res.ID_ AND t.ASSIGNEE_ = CAST(#{userId} AS VARCHAR)))
AND res.NAME_ LIKE CONCAT('%', #{reqVO.name}, '%') AND res.ID_ LIKE CONCAT('%', #{reqVO.processInstanceId}, '%') AND def.KEY_ = #{reqVO.processDefinitionKey} AND u.nickname LIKE CONCAT('%', #{reqVO.startUserNickname}, '%')
AND res.END_TIME_ IS NULL AND res.END_TIME_ IS NOT NULL AND (res.DELETE_REASON_ IS NULL OR res.DELETE_REASON_ = 'MI_END' OR LOWER(res.DELETE_REASON_) = 'completed') AND res.END_TIME_ IS NOT NULL AND res.DELETE_REASON_ IS NOT NULL AND res.DELETE_REASON_ != 'MI_END' AND LOWER(res.DELETE_REASON_) != 'completed'
AND EXISTS (SELECT 1 FROM ACT_HI_VARINST vr WHERE vr.PROC_INST_ID_ = res.ID_ AND vr.NAME_ = #{VAR_PROCESS_RESULT} AND (vr.LONG_ = #{reqVO.processResult} OR vr.TEXT_ = CAST(#{reqVO.processResult} AS VARCHAR)))
AND EXISTS (SELECT 1 FROM ACT_HI_VARINST v WHERE v.PROC_INST_ID_ = res.ID_ AND v.NAME_ = #{VAR_SOURCE_UNIT} AND v.TEXT_ LIKE CONCAT('%', #{reqVO.startDeptName}, '%'))
AND EXISTS (SELECT 1 FROM ACT_HI_VARINST v WHERE v.PROC_INST_ID_ = res.ID_ AND v.NAME_ = #{VAR_DEADLINE} AND ((v.LONG_ IS NOT NULL AND (CURRENT_DATE - DATE(to_timestamp(v.LONG_ / 1000))) >= #{reqVO.overdueDays}) OR (v.TEXT_ IS NOT NULL AND v.TEXT_ != '' AND (CURRENT_DATE - TO_DATE(v.TEXT_, 'YYYY-MM-DD')) >= #{reqVO.overdueDays})))
AND res.START_TIME_ BETWEEN #{reqVO.createTime[0]} AND #{reqVO.createTime[1]}
ORDER BY
res.NAME_ ASC res.NAME_ DESC def.NAME_ ASC def.NAME_ DESC sourceUnit ASC sourceUnit DESC urgencyDegree ASC urgencyDegree DESC res.START_TIME_ ASC res.START_TIME_ DESC deadlineDate ASC deadlineDate DESC status ASC status DESC currTaskName ASC currTaskName DESC currTaskAssignee ASC currTaskAssignee DESC res.START_TIME_ DESC
, res.ID_ DESC LIMIT #{reqVO.pageSize} OFFSET (#{reqVO.pageNo} - 1) * #{reqVO.pageSize}
